import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])
    idx = 2
    atk = []
    defense = []
    for _ in range(n):
        pos = data[idx]
        strength = int(data[idx + 1])
        idx += 2
        if pos == "ATK":
            atk.append(strength)
        else:
            defense.append(strength)
    ciel = []
    for _ in range(m):
        ciel.append(int(data[idx]))
        idx += 1

    atk_sorted = sorted(atk)
    ciel_sorted = sorted(ciel)
    len_atk = len(atk_sorted)
    len_ciel = len(ciel_sorted)

    dp = [[0] * (len_ciel + 1) for _ in range(len_atk + 1)]
    for i in range(1, len_atk + 1):
        for j in range(1, len_ciel + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
            if ciel_sorted[j - 1] >= atk_sorted[i - 1]:
                dp[i][j] = max(dp[i][j], dp[i - 1][j - 1] + ciel_sorted[j - 1] - atk_sorted[i - 1])
    ans1 = dp[len_atk][len_ciel]

    def_sorted = sorted(defense, reverse=True)
    atk_sorted_desc = sorted(atk, reverse=True)
    ciel_list = sorted(ciel)
    possible = True

    for d in def_sorted:
        found = False
        for i, c in enumerate(ciel_list):
            if c > d:
                ciel_list.pop(i)
                found = True
                break
        if not found:
            possible = False
            break

    if possible:
        for a in atk_sorted_desc:
            found = False
            for i, c in enumerate(ciel_list):
                if c >= a:
                    ciel_list.pop(i)
                    found = True
                    break
            if not found:
                possible = False
                break

    ans2 = 0
    if possible:
        ans2 = sum(ciel_list)

    print(max(ans1, ans2))

if __name__ == "__main__":
    solve()
